package io.github.chronicle.quietbelow.client;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import io.github.chronicle.core.client.ActionConfirmationScreen;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.screen.AccessibilityOnboardingScreen;
import net.minecraft.client.gui.screen.TitleScreen;
import net.minecraft.client.gui.screen.multiplayer.ConnectScreen;
import net.minecraft.client.network.ServerAddress;
import net.minecraft.client.network.ServerInfo;
import net.minecraft.client.util.ScreenshotRecorder;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.regex.Pattern;

/** Disposable two-client confirmation rehearsal; inert unless the private harness environment is set. */
public final class EcologyHeartSmoke {
    private static final String OUTPUT=System.getenv("CHRONICLE_HEART_SMOKE"), PHASE=System.getenv("CHRONICLE_HEART_PHASE"), ROLE=System.getenv("CHRONICLE_HEART_ROLE"), ROOT=System.getenv("CHRONICLE_HEART_SERVER_DIR");
    private static final Pattern PASS=Pattern.compile("^PASS Heart ([a-z_]+) \\(\\d+ checks\\)$",Pattern.CASE_INSENSITIVE);
    private final Path output,ready,safetyDone,offline,done; private final String phase,role; private final long deadline=System.nanoTime()+600_000_000_000L;
    private final List<String> messages=new ArrayList<>(),checks=new ArrayList<>();private final List<Step> steps=new ArrayList<>();
    private int index,base;private long until,stepDeadline;private boolean connected,built,started,finished;
    private EcologyHeartSmoke(String phase,String role,Path output,Path root)throws IOException{
        if(!List.of("initial","restart").contains(phase)||!List.of("A","B").contains(role))throw new IllegalArgumentException("invalid Heart smoke phase or role");
        if(!Files.isDirectory(root)||output.toAbsolutePath().normalize().startsWith(root.toAbsolutePath().normalize()))throw new IllegalArgumentException("Heart smoke needs an external report directory and staged server");
        this.phase=phase;this.role=role;this.output=output;Files.createDirectories(output);ready=output.resolve("heart-B-ready");safetyDone=output.resolve("heart-A-safety-done");offline=root.resolve("world").resolve("heart-B-offline");done=output.resolve("heart-A-done");
    }
    public static void register(){if(OUTPUT==null||PHASE==null||ROLE==null)return;try{if(ROOT==null)throw new IllegalArgumentException("missing staged server");var s=new EcologyHeartSmoke(PHASE,ROLE,Path.of(OUTPUT),Path.of(ROOT));ClientReceiveMessageEvents.GAME.register((t,o)->{if(!o&&!s.finished)s.messages.add(t.getString());});ClientTickEvents.END_CLIENT_TICK.register(s::tick);}catch(Exception e){setupFail(e);MinecraftClient.getInstance().scheduleStop();}}
    private void tick(MinecraftClient c){if(finished)return;try{need(System.nanoTime()<deadline,"Heart smoke timeout");if(c.player==null&&c.currentScreen instanceof AccessibilityOnboardingScreen)throw new IllegalStateException("accessibility onboarding");if(!connected&&c.getOverlay()==null&&c.currentScreen instanceof TitleScreen){connected=true;ConnectScreen.connect(c.currentScreen,c,ServerAddress.parse("127.0.0.1:25575"),new ServerInfo("Disposable Heart fixture","127.0.0.1:25575",ServerInfo.ServerType.OTHER),false,null);return;}if(c.player==null)return;if(!built){if(role.equals("A"))buildA(c);else buildB();built=true;}if(index>=steps.size()){finish(c,true,"Heart rehearsal complete");return;}Step s=steps.get(index);if(!started){base=messages.size();stepDeadline=System.nanoTime()+s.timeout*1_000_000L;s.start.run();started=true;}if(s.done.getAsBoolean()){checks.add(s.name);index++;started=false;}else need(System.nanoTime()<stepDeadline,"timed out: "+s.name);}catch(Throwable e){finish(c,false,e.getClass().getSimpleName()+": "+e.getMessage());}}
    private void buildA(MinecraftClient c){if(phase.equals("restart")){command("verify durable terminal record after restart","restart");screenshot("capture ended Heart model",c,"heart-ended-640.png");return;}command("prepare bound Relic Heart fixture","prepare");command("prepare real Heart item model","itemrender");step("select Heart hotbar item",()->c.player.getInventory().setSelectedSlot(8),()->c.player.getInventory().getSelectedSlot()==8,5_000);screenshot("capture actual bound Heart model",c,"heart-model-640.png");waitFor("wait for second actor",()->Files.exists(ready),40_000);command("verify root mutation and token safety","safety");waitFor("publish completed cross-actor safety",()->{marker(safetyDone);return true;},2_000);waitFor("wait for B durable disconnect marker",()->Files.exists(offline),40_000);command("verify B has disconnected before ending","offline");command("open actual bound Heart confirmation","open");waitFor("await ActionConfirmationScreen",()->c.currentScreen instanceof ActionConfirmationScreen,20_000);screenshot("capture Heart confirmation at GUI scale 2",c,"heart-confirm-640.png");step("resize Heart confirmation",()->c.getWindow().setWindowedSize(1280,720),()->c.getWindow().getFramebufferWidth()==1280,10_000);screenshot("capture wide Heart confirmation",c,"heart-confirm-1280.png");step("explicitly accept permanent Heart destruction",()->need(((ActionConfirmationScreen)c.currentScreen).triggerForTest("accept"),"Heart accept unavailable"),()->c.currentScreen instanceof ActionConfirmationScreen s&&s.state().completed(),30_000);step("close completed Heart confirmation",()->c.setScreen(null),()->c.currentScreen==null,5_000);waitFor("let bounded cleanup finish",()->Files.isRegularFile(Path.of(ROOT).resolve("world").resolve("heart-cleanup-measured.json")),150_000);command("verify terminal closure and loaded cleanup","ending");command("save terminal cleanup fixture","check");}
    private void buildB(){if(phase.equals("restart")){command("verify offline B receipt was removed","restart_b");return;}waitFor("announce independent second actor",()->{marker(ready);return true;},2_000);waitFor("wait until A completed cross-actor safety",()->Files.exists(safetyDone),40_000);waitFor("publish B disconnect marker",()->{return true;},2_000);}
    private void command(String name,String verb){step(name,()->send("quiet_below_heart_trial "+verb),()->received(verb),40_000);}private void waitFor(String n,BooleanSupplier done,long t){step(n,()->{},done,t);}private void step(String n,Runnable start,BooleanSupplier done,long timeout){steps.add(new Step(n,start,done,timeout));}private void send(String command){MinecraftClient.getInstance().player.networkHandler.sendChatCommand(command);}private boolean received(String verb){for(String m:messages.subList(base,messages.size())){if(m.toLowerCase().contains("fail heart"))throw new IllegalStateException(m);if(PASS.matcher(m).matches()&&m.toLowerCase().contains(verb))return true;}return false;}
    private void screenshot(String n,MinecraftClient c,String file){boolean[] sent={false};step(n,()->{c.inGameHud.getChatHud().clear(false);c.getToastManager().clear();until=System.nanoTime()+100_000_000L;},()->{if(System.nanoTime()<until)return false;if(!sent[0]){ScreenshotRecorder.saveScreenshot(output.toFile(),file,c.getFramebuffer(),1,x->{});sent[0]=true;}return pngReady(output.resolve("screenshots").resolve(file));},20_000);}private void marker(Path p){try{Files.writeString(p,role,StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException(e);}}
    private static boolean pngReady(Path path){try{if(!Files.isRegularFile(path))return false;byte[] b=Files.readAllBytes(path);int n=b.length;return n>24&&b[n-8]==73&&b[n-7]==69&&b[n-6]==78&&b[n-5]==68;}catch(IOException ignored){return false;}}
    private void finish(MinecraftClient c,boolean pass,String detail){if(finished)return;finished=true;if(role.equals("A")&&phase.equals("initial"))marker(done);try{JsonObject r=new JsonObject();r.addProperty("result",pass?"PASS":"FAIL");r.addProperty("phase",phase);r.addProperty("role",role);r.addProperty("detail",detail);r.add("checks",new Gson().toJsonTree(checks));r.add("messages",new Gson().toJsonTree(messages));Files.writeString(output.resolve("heart-"+phase+"-"+role+".json"),new Gson().toJson(r),StandardCharsets.UTF_8);}catch(IOException ignored){}c.scheduleStop();}private static void need(boolean b,String m){if(!b)throw new IllegalStateException(m);}private record Step(String name,Runnable start,BooleanSupplier done,long timeout){}private static void setupFail(Exception e){try{if(OUTPUT!=null){Path o=Path.of(OUTPUT);Files.createDirectories(o);Files.writeString(o.resolve("heart-"+PHASE+"-"+ROLE+".json"),"{\"result\":\"FAIL\",\"detail\":\"setup: "+e.getMessage().replace("\"","'")+"\"}");}}catch(Exception ignored){}}
}
